def assert_response(responseBody, globalParam, statusCode, headers):
    if not (statusCode == 200 and isinstance(responseBody, dict) and responseBody.get("code") == 0):
        raise Blocked("社区准备查询失败")
    data = responseBody.get("data")
    if not isinstance(data, list) or not data or not isinstance(data[0], dict) or not data[0].get("id"):
        raise Blocked("没有可用社区且没有公开社区创建 HTTP 接口")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if not (statusCode == 200 and isinstance(responseBody, dict) and responseBody.get("code") == 0):
        raise Blocked("注册准备失败；不得删除既有账号")
    data = responseBody.get("data", {})
    return bool(data.get("user", {}).get("id") and data.get("accessToken") and data.get("refreshToken"))
